# === Module: calendar.limudim ===


class LimudimError(Error):
    """Base exception for the `calendar.limudim` module's error domain."""

    InvalidUnit: Type[InvalidUnit]


class InvalidUnit(LimudimError):
    """A psalm outside 1 to 150, a verse outside 1 to 176, a chapter of Pirkei Avos outside 1
    to 6, or a range that ends before it starts.
    """

    CODE = 1

    def __init__(self, message: str = "A psalm outside 1 to 150, a verse outside 1 to 176, a chapter of Pirkei Avos outside 1") -> None:
        super().__init__(1, message)


LimudimError.InvalidUnit = InvalidUnit


def _limudim_error_from(code: int, message: str, payload: bytes = b"") -> Error:
    """The LimudimError subclass for `code` with its payload fields, or the
    plain Error for a runtime code (a panic, a marshalling failure).
    """
    if code == 1:
        return InvalidUnit(message)
    return Error(code, message)


