@dataclass
class MishnaPair:
    """The two *mishnayos* of a day of Mishna Yomis."""

    # The first *mishnah*.
    first: Mishna
    # The second, the next *mishnah* in order.
    second: Mishna
    # As text, for example "Nazir 5:5-6".
    display: str


def _write_MishnaPair(_w: _Writer, value: MishnaPair) -> None:
    _write_Mishna(_w, value.first)
    _write_Mishna(_w, value.second)
    _w.write_string(value.display)


def _read_MishnaPair(_r: _Reader) -> MishnaPair:
    return MishnaPair(
        first=_read_Mishna(_r),
        second=_read_Mishna(_r),
        display=_r.read_string(),
    )


