# === Module: times ===


class ZmanimError(Error):
    """Base exception for the `times` module's error domain."""

    InvalidLatitude: Type[InvalidLatitude]
    InvalidLongitude: Type[InvalidLongitude]
    InvalidElevation: Type[InvalidElevation]
    InvalidGregorianDate: Type[InvalidGregorianDate]
    TimeZoneRequired: Type[TimeZoneRequired]
    InvalidLocalDay: Type[InvalidLocalDay]
    InvalidMinutes: Type[InvalidMinutes]
    InvalidDegrees: Type[InvalidDegrees]
    AllDay: Type[AllDay]
    AllNight: Type[AllNight]
    NotApplicable: Type[NotApplicable]
    Unexpected: Type[Unexpected]


class InvalidLatitude(ZmanimError):
    """The latitude is not between -90 and 90 degrees."""

    CODE = 1

    def __init__(self, message: str = "The latitude is not between -90 and 90 degrees.") -> None:
        super().__init__(1, message)


class InvalidLongitude(ZmanimError):
    """The longitude is not between -180 and 180 degrees."""

    CODE = 2

    def __init__(self, message: str = "The longitude is not between -180 and 180 degrees.") -> None:
        super().__init__(2, message)


class InvalidElevation(ZmanimError):
    """An elevation is negative or not a finite number."""

    CODE = 3

    def __init__(self, message: str = "An elevation is negative or not a finite number.") -> None:
        super().__init__(3, message)


class InvalidGregorianDate(ZmanimError):
    """The Gregorian date does not exist, or is outside the supported range."""

    CODE = 4

    def __init__(self, message: str = "The Gregorian date does not exist, or is outside the supported range.") -> None:
        super().__init__(4, message)


class TimeZoneRequired(ZmanimError):
    """A local day is needed and none was given. The four Kiddush Levana times need one.
    `Zmanim` and `MyZmanim` also need one at a location more than 150 degrees from
    Greenwich.
    """

    CODE = 5

    def __init__(self, message: str = "A local day is needed and none was given. The four Kiddush Levana times need one.") -> None:
        super().__init__(5, message)


class InvalidLocalDay(ZmanimError):
    """The local day is impossible.

    It ends before it starts or more than 48 hours after, or an offset is a day or more.
    """

    CODE = 6

    def __init__(self, message: str = "The local day is impossible.") -> None:
        super().__init__(6, message)


class InvalidMinutes(ZmanimError):
    """A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number
    within a day (1440 minutes) either way.
    """

    CODE = 7

    def __init__(self, message: str = "A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number") -> None:
        super().__init__(7, message)


class InvalidDegrees(ZmanimError):
    """An angle in degrees is not a number from -90 to 90."""

    CODE = 8

    def __init__(self, message: str = "An angle in degrees is not a number from -90 to 90.") -> None:
        super().__init__(8, message)


class AllDay(ZmanimError):
    """The sun stays above the angle the time needs all day, as in the far north in summer."""

    CODE = 10

    def __init__(self, message: str = "The sun stays above the angle the time needs all day, as in the far north in summer.") -> None:
        super().__init__(10, message)


class AllNight(ZmanimError):
    """The sun stays below the angle the time needs all day, as in the far north in winter."""

    CODE = 11

    def __init__(self, message: str = "The sun stays below the angle the time needs all day, as in the far north in winter.") -> None:
        super().__init__(11, message)


class NotApplicable(ZmanimError):
    """The time only exists on certain dates, and this is not one."""

    CODE = 12

    def __init__(self, message: str = "The time only exists on certain dates, and this is not one.") -> None:
        super().__init__(12, message)


class Unexpected(ZmanimError):
    """A calculation failed in a way that should not happen; please report the location and
    date.
    """

    CODE = 13

    def __init__(self, message: str = "A calculation failed in a way that should not happen; please report the location and") -> None:
        super().__init__(13, message)


ZmanimError.InvalidLatitude = InvalidLatitude
ZmanimError.InvalidLongitude = InvalidLongitude
ZmanimError.InvalidElevation = InvalidElevation
ZmanimError.InvalidGregorianDate = InvalidGregorianDate
ZmanimError.TimeZoneRequired = TimeZoneRequired
ZmanimError.InvalidLocalDay = InvalidLocalDay
ZmanimError.InvalidMinutes = InvalidMinutes
ZmanimError.InvalidDegrees = InvalidDegrees
ZmanimError.AllDay = AllDay
ZmanimError.AllNight = AllNight
ZmanimError.NotApplicable = NotApplicable
ZmanimError.Unexpected = Unexpected


def _zmanim_error_from(code: int, message: str, payload: bytes = b"") -> Error:
    """The ZmanimError subclass for `code` with its payload fields, or the
    plain Error for a runtime code (a panic, a marshalling failure).
    """
    if code == 1:
        return InvalidLatitude(message)
    if code == 2:
        return InvalidLongitude(message)
    if code == 3:
        return InvalidElevation(message)
    if code == 4:
        return InvalidGregorianDate(message)
    if code == 5:
        return TimeZoneRequired(message)
    if code == 6:
        return InvalidLocalDay(message)
    if code == 7:
        return InvalidMinutes(message)
    if code == 8:
        return InvalidDegrees(message)
    if code == 10:
        return AllDay(message)
    if code == 11:
        return AllNight(message)
    if code == 12:
        return NotApplicable(message)
    if code == 13:
        return Unexpected(message)
    return Error(code, message)


