class Category(IntEnum):
    """What kind of time a `Zman` is."""

    # Start and end of astronomical, civil and nautical twilight.
    Twilight = 0
    # Dawn (*alos*).
    Alos = 1
    # Earliest time for tallis and tefillin (*misheyakir*).
    Misheyakir = 2
    # Sunrise (*netz*).
    Netz = 3
    # Latest time for the morning Shema.
    SofZmanShma = 4
    # Latest time for the morning prayer.
    SofZmanTefila = 5
    # Latest time to eat chametz on Erev Pesach.
    SofZmanAchilasChametz = 6
    # Latest time to burn chametz on Erev Pesach.
    SofZmanBiurChametz = 7
    # Midday (*chatzos hayom*).
    ChatzosHayom = 8
    # Earliest Mincha (*mincha gedola*).
    MinchaGedola = 9
    # *Plag hamincha*.
    PlagHamincha = 10
    # Shortly before *mincha ketana*.
    SamuchLeMinchaKetana = 11
    # Preferred Mincha time (*mincha ketana*).
    MinchaKetana = 12
    # Twilight between sunset and nightfall (*bein hashmashos*).
    BeinHashmashos = 13
    # Candle lighting before Shabbos or Yom Tov.
    CandleLighting = 14
    # Sunset (*shkiya*).
    Shkiya = 15
    # Nightfall (*tzais*).
    Tzais = 16
    # The window for Kiddush Levana.
    KidushLevana = 17
    # Midnight (*chatzos halayla*).
    ChatzosHalayla = 18


class Calculator(IntEnum):
    """The solar position algorithm."""

    # The NOAA algorithm, KosherJava's default. Good to about a minute.
    Noaa = 0
    # Jean Meeus's higher-accuracy VSOP87 algorithm.
    Meeus = 1
    # The NREL Solar Position Algorithm, solved on the topocentric zenith.
    Spa = 2


class ZmanFailure(IntEnum):
    """Why a time in `ZmanTime` could not be calculated."""

    # The sun stays above the angle the time needs all day.
    AllDay = 0
    # The sun stays below the angle the time needs all day.
    AllNight = 1
    # The time does not apply on this date.
    NotApplicable = 2
    # The time needs a local day and none was given. Only the four Kiddush Levana times need
    # one.
    TimeZoneRequired = 3
    # An internal calculation error.
    Unexpected = 5


@dataclass
class Location:
    """A place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
    leave them 0 for sea level.

    The time zone is not part of the location. You pass a `LocalDay` to `Zmanim` and
    `MyZmanim` when you create them.
    """

    # Latitude in degrees, north positive.
    latitude: float
    # Longitude in degrees, east positive.
    longitude: float
    # The observer's height. Elevation makes sunrise earlier and sunset later.
    elevation: float
    # The height of the eastern horizon, over which the sun rises.
    eastern_horizon_elevation: float
    # The height of the western horizon, behind which the sun sets.
    western_horizon_elevation: float


def _write_Location(_w: _Writer, value: Location) -> None:
    _w.write_f64(value.latitude)
    _w.write_f64(value.longitude)
    _w.write_f64(value.elevation)
    _w.write_f64(value.eastern_horizon_elevation)
    _w.write_f64(value.western_horizon_elevation)


def _read_Location(_r: _Reader) -> Location:
    return Location(
        latitude=_r.read_f64(),
        longitude=_r.read_f64(),
        elevation=_r.read_f64(),
        eastern_horizon_elevation=_r.read_f64(),
        western_horizon_elevation=_r.read_f64(),
    )


@dataclass
class LocalDay:
    """The date in the caller's time zone: when local midnight starts it, when local midnight
    starts the next date, and the offset from UTC at each. Compute it with your platform's
    time zone support, for example `date.atStartOfDay(zone)` and
    `date.plusDays(1).atStartOfDay(zone)` in Java.

    When the clocks skip midnight, the day starts at the first instant the clocks show that
    day, such as 01:00. A day the clocks skip entirely starts and ends at the same instant.

    The local day is optional. With one every time works. You can also leave it out. These do
    not work without one:

    - The four Kiddush Levana times return `ZmanimError::TimeZoneRequired`.
    - `Zmanim` and `MyZmanim` cannot be created for a location more than 150 degrees from
      Greenwich. Creating them returns `ZmanimError::TimeZoneRequired`.
    """

    # When local midnight starts the date, in Unix milliseconds.
    start_ms: int
    # The offset from UTC at `start_ms`, in seconds east.
    start_offset_seconds: int
    # When local midnight starts the next date, in Unix milliseconds.
    end_ms: int
    # The offset from UTC at `end_ms`, in seconds east.
    end_offset_seconds: int


def _write_LocalDay(_w: _Writer, value: LocalDay) -> None:
    _w.write_i64(value.start_ms)
    _w.write_i32(value.start_offset_seconds)
    _w.write_i64(value.end_ms)
    _w.write_i32(value.end_offset_seconds)


def _read_LocalDay(_r: _Reader) -> LocalDay:
    return LocalDay(
        start_ms=_r.read_i64(),
        start_offset_seconds=_r.read_i32(),
        end_ms=_r.read_i64(),
        end_offset_seconds=_r.read_i32(),
    )


@dataclass
class Config:
    """How `Zmanim` calculates. `default_config` matches KosherJava's defaults."""

    # How long before sea-level sunset candle lighting is, in minutes, from 0 to 1440.
    # Default 18.
    candle_lighting_minutes: int
    # Whether proportional zmanim divide the day at astronomical *chatzos*. Default false.
    use_astronomical_chatzos_for_other_zmanim: bool
    # Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
    # and sunset themselves. Default false.
    use_elevation: bool
    # How long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
    # Default 40.
    ateret_torah_sunset_minutes: int
    # Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
    # sunset. Default true.
    use_astronomical_chatzos: bool
    # The solar position algorithm. Default NOAA.
    calculator: Calculator
    # For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.
    apply_delta_t: bool


